    given: '{1} 人获得', bydate: '依日期（{t1}）', typedfor: '{1} 的手动输入分数', addfor: '为 {1} 添加分数', xcfor: '{1} 的加分', scfor: '{1} 的分数', ofxc: '{2} 人中 {1} 人有加分', ofdone: '{2} 人中 {1} 人完成', ofent: '{2} 人中 {1} 人已输入', xcI: '每一分会让“{t1}”增加一个百分点，再依其比重计入。不加分的学生请留白。不会改变任何作业的分数。',
